    /// <item><description>"S32LE": Signed 32-bit little-endian audio</description></item>
    /// <item><description>"S32BE": Signed 32-bit big-endian audio</description></item>
    /// <item><description>"S32": Signed 32-bit native-endian audio</description></item>
    /// <item><description>"F32LE": Floating point little-endian audio</description></item>
    /// <item><description>"F32BE": Floating point big-endian audio</description></item>
    /// <item><description>"F32": Floating point native-endian audio</description></item>
