    /// <summary>Prevent SDL from using version 4 of the bitmap header when saving BMPs.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_BMP_SAVE_LEGACY_FORMAT</c>.</para>
    /// <para>The value is <c>SDL_BMP_SAVE_LEGACY_FORMAT</c>.</para>
    /// <para>
    /// The bitmap header version 4 is required for proper alpha channel support and SDL will use it when required.
    /// Should this not be desired, this hint can force the use of the 40 byte header version which is supported
    /// everywhere.
    /// </para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item>
    /// <description>"0": Surfaces with a colorkey or an alpha channel are saved to a 32-bit BMP file with an alpha
    /// mask. SDL will use the bitmap header version 4 and set the alpha mask accordingly. (default)</description>
    /// </item>
    /// <item>
    /// <description>"1": Surfaces with a colorkey or an alpha channel are saved to a 32-bit BMP file without an alpha
    /// mask. The alpha channel data will be in the file, but applications are going to ignore it.</description>
    /// </item>
    /// </list>
    /// <para>This hint can be set anytime.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintBmpSaveLegacyFormat => "SDL_BMP_SAVE_LEGACY_FORMAT"u8;

