    /// <item><description>"sse2"</description></item>
    /// <item><description>"sse3"</description></item>
    /// <item><description>"sse41"</description></item>
    /// <item><description>"sse42"</description></item>
    /// <item><description>"avx"</description></item>
    /// <item><description>"avx2"</description></item>
    /// <item><description>"avx512f"</description></item>
    /// <item><description>"arm-simd"</description></item>
    /// <item><description>"neon"</description></item>
    /// <item><description>"lsx"</description></item>
    /// <item><description>"lasx"</description></item>
    /// </list>
    /// <para>The items can be prefixed by '+'/'-' to add/remove features.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintCpuFeatureMask => "SDL_CPU_FEATURE_MASK"u8;

