    /// <summary>A variable that controls keycode representation in keyboard events.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_KEYCODE_OPTIONS</c>.</para>
    /// <para>The value is <c>SDL_KEYCODE_OPTIONS</c>.</para>
    /// <para>This variable is a comma separated set of options for translating keycodes in events:</para>
    /// <list type="bullet">
    /// <item><description>"none": Keycode options are cleared, this overrides other options.</description></item>
    /// <item>
    /// <description>"hide_numpad": The numpad keysyms will be translated into their non-numpad versions based on the
    /// current NumLock state. For example, SDLK_KP_4 would become SDLK_4 if SDL_KMOD_NUM is set in the event modifiers,
    /// and SDLK_LEFT if it is unset.</description>
    /// </item>
    /// <item>
    /// <description>"french_numbers": The number row on French keyboards is inverted, so pressing the 1 key would yield
    /// the keycode SDLK_1, or '1', instead of SDLK_AMPERSAND, or '&amp;'</description>
    /// </item>
    /// <item>
    /// <description>"latin_letters": For keyboards using non-Latin letters, such as Russian or Thai, the letter keys
    /// generate keycodes as though it had an English QWERTY layout. e.g. pressing the key associated with
    /// SDL_SCANCODE_A on a Russian keyboard would yield 'a' instead of a Cyrillic letter.</description>
    /// </item>
    /// </list>
    /// <para>The default value for this hint is "french_numbers,latin_letters"</para>
    /// <para>Some platforms like Emscripten only provide modified keycodes and the options are not used.</para>
    /// <para>
    /// These options do not affect the return value of SDL_GetKeyFromScancode() or SDL_GetScancodeFromKey(), they just
    /// apply to the keycode included in key events.
    /// </para>
    /// <para>This hint can be set anytime.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintKeycodeOptions => "SDL_KEYCODE_OPTIONS"u8;

