    /// <remarks>
    /// <para>Binds <c>SDL_HINT_MAC_OPENGL_ASYNC_DISPATCH</c>.</para>
    /// <para>The value is <c>SDL_MAC_OPENGL_ASYNC_DISPATCH</c>.</para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item>
