    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item><description>"0": Ignore mouse clicks that activate a window. (default)</description></item>
    /// <item><description>"1": Generate events for mouse clicks that activate a window.</description></item>
    /// </list>
    /// <para>This hint can be set anytime.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintMouseFocusClickthrough => "SDL_MOUSE_FOCUS_CLICKTHROUGH"u8;

