    /// <summary>
    /// A variable controlling whether relative mouse mode constrains the mouse to the center of the window.
    /// </summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_MOUSE_RELATIVE_MODE_CENTER</c>.</para>
    /// <para>The value is <c>SDL_MOUSE_RELATIVE_MODE_CENTER</c>.</para>
    /// <para>
    /// Constraining to the center of the window works better for FPS games and when the application is running over
    /// RDP. Constraining to the whole window works better for 2D games and increases the chance that the mouse will be
    /// in the correct position when using high DPI mice.
    /// </para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item><description>"0": Relative mouse mode constrains the mouse to the window.</description></item>
    /// <item>
    /// <description>"1": Relative mouse mode constrains the mouse to the center of the window. (default)</description>
    /// </item>
    /// </list>
    /// <para>This hint can be set anytime.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintMouseRelativeModeCenter => "SDL_MOUSE_RELATIVE_MODE_CENTER"u8;

