    /// <para>The value is <c>SDL_MOUSE_RELATIVE_SPEED_SCALE</c>.</para>
    /// <para>This hint can be set anytime.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintMouseRelativeSpeedScale => "SDL_MOUSE_RELATIVE_SPEED_SCALE"u8;

