    public static ReadOnlySpan<byte> HintMouseRelativeSystemScale => "SDL_MOUSE_RELATIVE_SYSTEM_SCALE"u8;

    /// <summary>
    /// A variable controlling whether a motion event should be generated for mouse warping in relative mode.
    /// </summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_MOUSE_RELATIVE_WARP_MOTION</c>.</para>
    /// <para>The value is <c>SDL_MOUSE_RELATIVE_WARP_MOTION</c>.</para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item><description>"0": Warping the mouse will not generate a motion event in relative mode</description></item>
    /// <item><description>"1": Warping the mouse will generate a motion event in relative mode</description></item>
    /// </list>
    /// <para>
