    /// having to filter out large relative motion due to warping.
    /// </para>
    /// <para>This hint can be set anytime.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintMouseRelativeWarpMotion => "SDL_MOUSE_RELATIVE_WARP_MOTION"u8;

