    /// <para>The value is <c>SDL_OPENGL_LIBRARY</c>.</para>
    /// <para>
    /// This hint should be set before creating an OpenGL window or creating an OpenGL context. If this hint isn't set,
    /// SDL will choose a reasonable default.
    /// </para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintOpenGLLibrary => "SDL_OPENGL_LIBRARY"u8;

    /// <summary>Specify the EGL library to load.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_EGL_LIBRARY</c>.</para>
    /// <para>The value is <c>SDL_EGL_LIBRARY</c>.</para>
    /// <para>
    /// This hint should be set before creating an OpenGL window or creating an OpenGL context. This hint is only
    /// considered if SDL is using EGL to manage OpenGL contexts. If this hint isn't set, SDL will choose a reasonable
    /// default.
    /// </para>
    /// <para>This hint is available since SDL 3.2.0.</para>
