    public static ReadOnlySpan<byte> HintEglLibrary => "SDL_EGL_LIBRARY"u8;

    /// <summary>A variable controlling what driver to use for OpenGL ES contexts.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_OPENGL_ES_DRIVER</c>.</para>
    /// <para>The value is <c>SDL_OPENGL_ES_DRIVER</c>.</para>
    /// <para>
    /// On some platforms, currently Windows and X11, OpenGL drivers may support creating contexts with an OpenGL ES
    /// profile. By default SDL uses these profiles, when available, otherwise it attempts to load an OpenGL ES library,
    /// e.g. that provided by the ANGLE project. This variable controls whether SDL follows this default behaviour or
    /// will always load an OpenGL ES library.
    /// </para>
    /// <para>
    /// Circumstances where this is useful include - Testing an app with a particular OpenGL ES implementation, e.g
    /// ANGLE, or emulator, e.g. those from ARM, Imagination or Qualcomm. - Resolving OpenGL ES function addresses at
    /// link time by linking with the OpenGL ES library instead of querying them at run time with
    /// SDL_GL_GetProcAddress().
    /// </para>
    /// <para>
    /// Caution: for an application to work with the default behaviour across different OpenGL drivers it must query the
    /// OpenGL ES function addresses at run time using SDL_GL_GetProcAddress().
    /// </para>
    /// <para>This variable is ignored on most platforms because OpenGL ES is native or not supported.</para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item><description>"0": Use ES profile of OpenGL, if available. (default)</description></item>
    /// <item><description>"1": Load OpenGL ES library using the default library names.</description></item>
    /// </list>
    /// <para>This hint should be set before SDL is initialized.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintOpenGLEsDriver => "SDL_OPENGL_ES_DRIVER"u8;

    /// <summary>A variable controlling whether to force an sRGB-capable OpenGL context.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_OPENGL_FORCE_SRGB_FRAMEBUFFER</c>.</para>
    /// <para>The value is <c>SDL_OPENGL_FORCE_SRGB_FRAMEBUFFER</c>.</para>
    /// <para>
    /// At OpenGL context creation time, some platforms can request an sRGB-capable context. However, sometimes any form
    /// of the request can cause surprising results on some drivers, platforms, and hardware. Usually the surprise is in
    /// the form of rendering that is either a little darker or a little brighter than intended.
    /// </para>
    /// <para>
    /// This hint allows the user to override the app's sRGB requests and either force a specific value, or avoid
    /// requesting anything at all, depending on what makes things work correctly for their system.
    /// </para>
    /// <para>
    /// This is meant as a fail-safe; apps should probably not explicitly set this, and most users should not, either.
    /// </para>
    /// <para>
    /// Note that some platforms cannot make this request at all, and on all platforms this request can be denied by the
    /// operating system.
    /// </para>
    /// <para>
    /// In addition to attempting to obtain the type of sRGB-capable OpenGL context requested by this hint, SDL will try
    /// to force the state of GL_FRAMEBUFFER_SRGB on the new context, if appropriate.
    /// </para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item><description>"0": Force a request for an OpenGL context that is _not_ sRGB-capable.</description></item>
    /// <item><description>"1": Force a request for an OpenGL context that _is_ sRGB-capable.</description></item>
    /// <item>
    /// <description>"skip": Don't make any request for an sRGB-capable context (don't specify the attribute at all
    /// during context creation time).</description>
    /// </item>
    /// <item><description>any other string is undefined behavior.</description></item>
    /// </list>
    /// <para>
    /// If unset, or set to an empty string, SDL will make a request using the value the app specified with the
    /// SDL_GL_FRAMEBUFFER_SRGB_CAPABLE attribute.
    /// </para>
    /// <para>This hint should be set before an OpenGL context is created.</para>
    /// <para>This hint is available since SDL 3.4.2.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintOpenGLForceSrgbFramebuffer => "SDL_OPENGL_FORCE_SRGB_FRAMEBUFFER"u8;

    /// <summary>Mechanism to specify openvr_api library location</summary>
    /// <remarks>
