    /// <para>
    /// The format of this hint is a comma-separated list of language and locale, combined with an underscore, as is a
    /// common format: "en_GB". Locale is optional: "en". So you might have a list like this: "en_GB,jp,es_PT"
    /// </para>
    /// <para>This hint can be set anytime.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintPreferredLocales => "SDL_PREFERRED_LOCALES"u8;

    /// <summary>A variable that decides whether to send SDL_EVENT_QUIT when closing the last window.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_QUIT_ON_LAST_WINDOW_CLOSE</c>.</para>
    /// <para>The value is <c>SDL_QUIT_ON_LAST_WINDOW_CLOSE</c>.</para>
