    /// <para>This hint can be set anytime.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintTouchMouseEvents => "SDL_TOUCH_MOUSE_EVENTS"u8;

    /// <summary>A variable controlling whether trackpads should be treated as touch devices.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_TRACKPAD_IS_TOUCH_ONLY</c>.</para>
    /// <para>The value is <c>SDL_TRACKPAD_IS_TOUCH_ONLY</c>.</para>
    /// <para>
    /// On macOS (and possibly other platforms in the future), SDL will report touches on a trackpad as mouse input,
    /// which is generally what users expect from this device; however, these are often actually full multitouch-capable
    /// touch devices, so it might be preferable to some apps to treat them as such.
    /// </para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item><description>"0": Trackpad will send mouse events. (default)</description></item>
    /// <item><description>"1": Trackpad will send touch events.</description></item>
    /// </list>
    /// <para>This hint should be set before SDL is initialized.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintTrackpadIsTouchOnly => "SDL_TRACKPAD_IS_TOUCH_ONLY"u8;

    /// <summary>
    /// A variable controlling whether the Android / tvOS remotes should be listed as joystick devices, instead of
    /// sending keyboard events.
    /// </summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_TV_REMOTE_AS_JOYSTICK</c>.</para>
    /// <para>The value is <c>SDL_TV_REMOTE_AS_JOYSTICK</c>.</para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item><description>"0": Remotes send enter/escape/arrow key events.</description></item>
    /// <item><description>"1": Remotes are available as 2 axis, 2 button joysticks. (default)</description></item>
    /// </list>
    /// <para>This hint should be set before SDL is initialized.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintTvRemoteAsJoystick => "SDL_TV_REMOTE_AS_JOYSTICK"u8;

    /// <summary>A variable controlling whether the screensaver is enabled.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_ALLOW_SCREENSAVER</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_ALLOW_SCREENSAVER</c>.</para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item><description>"0": Disable screensaver. (default)</description></item>
    /// <item><description>"1": Enable screensaver.</description></item>
    /// </list>
    /// <para>This hint should be set before SDL is initialized.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoAllowScreensaver => "SDL_VIDEO_ALLOW_SCREENSAVER"u8;

    /// <summary>
    /// A comma separated list containing the names of the displays that SDL should sort to the front of the display
    /// list.
    /// </summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_DISPLAY_PRIORITY</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_DISPLAY_PRIORITY</c>.</para>
    /// <para>
    /// When this hint is set, displays with matching name strings will be prioritized in the list of displays, as
    /// exposed by calling SDL_GetDisplays(), with the first listed becoming the primary display. The naming convention
    /// can vary depending on the environment, but it is usually a connector name (e.g. 'DP-1', 'DP-2', 'HDMI-A-1',
    /// etc...).
    /// </para>
    /// <para>
    /// On Wayland desktops, the connector names associated with displays can be found in the <c>name</c> property of
    /// the info output from <c>wayland-info -i wl_output</c>. On X11 desktops, the <c>xrandr</c> utility can be used to
    /// retrieve the connector names associated with displays.
    /// </para>
    /// <para>This hint is currently supported on the following drivers:</para>
    /// <list type="bullet">
    /// <item><description>KMSDRM (kmsdrm)</description></item>
    /// <item><description>Wayland (wayland)</description></item>
    /// <item><description>X11 (x11)</description></item>
    /// </list>
    /// <para>This hint should be set before SDL is initialized.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoDisplayPriority => "SDL_VIDEO_DISPLAY_PRIORITY"u8;

    /// <summary>Tell the video driver that we only want a double buffer.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_DOUBLE_BUFFER</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_DOUBLE_BUFFER</c>.</para>
    /// <para>
    /// By default, most lowlevel 2D APIs will use a triple buffer scheme that wastes no CPU time on waiting for vsync
    /// after issuing a flip, but introduces a frame of latency. On the other hand, using a double buffer scheme instead
    /// is recommended for cases where low latency is an important factor because we save a whole frame of latency.
    /// </para>
    /// <para>
    /// We do so by waiting for vsync immediately after issuing a flip, usually just after eglSwapBuffers call in the
    /// backend's *_SwapWindow function.
    /// </para>
    /// <para>This hint is currently supported on the following drivers:</para>
    /// <list type="bullet">
    /// <item><description>Raspberry Pi (raspberrypi)</description></item>
    /// <item><description>Wayland (wayland)</description></item>
    /// </list>
    /// <para>This hint should be set before SDL is initialized.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoDoubleBuffer => "SDL_VIDEO_DOUBLE_BUFFER"u8;

    /// <summary>A variable that specifies a video backend to use.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_DRIVER</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_DRIVER</c>.</para>
    /// <para>
    /// By default, SDL will try all available video backends in a reasonable order until it finds one that can work,
    /// but this hint allows the app or user to force a specific target, such as "x11" if, say, you are on Wayland but
    /// want to try talking to the X server instead.
    /// </para>
    /// <para>
    /// This hint accepts a comma-separated list of driver names, and each will be tried in the order listed during
    /// init, until one succeeds or all of them fail.
    /// </para>
    /// <para>This hint should be set before SDL is initialized.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoDriver => "SDL_VIDEO_DRIVER"u8;

    /// <summary>A variable controlling whether the dummy video driver saves output frames.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_DUMMY_SAVE_FRAMES</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_DUMMY_SAVE_FRAMES</c>.</para>
    /// <list type="bullet">
    /// <item><description>"0": Video frames are not saved to disk. (default)</description></item>
    /// <item>
    /// <description>"1": Video frames are saved to files in the format "SDL_windowX-Y.bmp", where X is the window ID,
    /// and Y is the frame number.</description>
    /// </item>
    /// </list>
    /// <para>This hint can be set anytime.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoDummySaveFrames => "SDL_VIDEO_DUMMY_SAVE_FRAMES"u8;

    /// <summary>If eglGetPlatformDisplay fails, fall back to calling eglGetDisplay.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_EGL_ALLOW_GETDISPLAY_FALLBACK</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_EGL_ALLOW_GETDISPLAY_FALLBACK</c>.</para>
    /// <para>The variable can be set to one of the following values:</para>
    /// <list type="bullet">
    /// <item><description>"0": Do not fall back to eglGetDisplay.</description></item>
    /// <item>
    /// <description>"1": Fall back to eglGetDisplay if eglGetPlatformDisplay fails. (default)</description>
    /// </item>
    /// </list>
    /// <para>This hint should be set before SDL is initialized.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoEglAllowGetdisplayFallback => "SDL_VIDEO_EGL_ALLOW_GETDISPLAY_FALLBACK"u8;

    /// <summary>A variable controlling whether the OpenGL context should be created with EGL.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_FORCE_EGL</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_FORCE_EGL</c>.</para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item>
    /// <description>"0": Use platform-specific GL context creation API (GLX, WGL, CGL, etc). (default)</description>
    /// </item>
    /// <item><description>"1": Use EGL</description></item>
    /// </list>
    /// <para>This hint should be set before SDL is initialized.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoForceEgl => "SDL_VIDEO_FORCE_EGL"u8;

    /// <summary>A variable that specifies the policy for fullscreen Spaces on macOS.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_MAC_FULLSCREEN_SPACES</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_MAC_FULLSCREEN_SPACES</c>.</para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item>
    /// <description>"0": Disable Spaces support (FULLSCREEN_DESKTOP won't use them and SDL_WINDOW_RESIZABLE windows
    /// won't offer the "fullscreen" button on their titlebars).</description>
    /// </item>
    /// <item>
    /// <description>"1": Enable Spaces support (FULLSCREEN_DESKTOP will use them and SDL_WINDOW_RESIZABLE windows will
    /// offer the "fullscreen" button on their titlebars). (default)</description>
    /// </item>
    /// </list>
    /// <para>This hint should be set before creating a window.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoMacFullscreenSpaces => "SDL_VIDEO_MAC_FULLSCREEN_SPACES"u8;

    /// <summary>A variable that specifies the menu visibility when a window is fullscreen in Spaces on macOS.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_MAC_FULLSCREEN_MENU_VISIBILITY</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_MAC_FULLSCREEN_MENU_VISIBILITY</c>.</para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item>
    /// <description>"0": The menu will be hidden when the window is in a fullscreen space, and not accessible by moving
    /// the mouse to the top of the screen.</description>
    /// </item>
    /// <item>
    /// <description>"1": The menu will be accessible when the window is in a fullscreen space.</description>
    /// </item>
    /// <item>
    /// <description>"auto": The menu will be hidden if fullscreen mode was toggled on programmatically via
    /// <c>SDL_SetWindowFullscreen()</c>, and accessible if fullscreen was entered via the "fullscreen" button on the
    /// window title bar. (default)</description>
    /// </item>
    /// </list>
    /// <para>This hint can be set anytime.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoMacFullscreenMenuVisibility => "SDL_VIDEO_MAC_FULLSCREEN_MENU_VISIBILITY"u8;

    /// <summary>
    /// A variable indicating whether the metal layer drawable size should be updated for the
    /// SDL_EVENT_WINDOW_PIXEL_SIZE_CHANGED event on macOS.
    /// </summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_METAL_AUTO_RESIZE_DRAWABLE</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_METAL_AUTO_RESIZE_DRAWABLE</c>.</para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item>
    /// <description>"0": the metal layer drawable size will not be updated on the SDL_EVENT_WINDOW_PIXEL_SIZE_CHANGED
    /// event.</description>
    /// </item>
    /// <item>
    /// <description>"1": the metal layer drawable size will be updated on the SDL_EVENT_WINDOW_PIXEL_SIZE_CHANGED
    /// event. (default)</description>
    /// </item>
    /// </list>
    /// <para>This hint should be set before SDL_Metal_CreateView called.</para>
    /// <para>This hint is available since SDL 3.4.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoMetalAutoResizeDrawable => "SDL_VIDEO_METAL_AUTO_RESIZE_DRAWABLE"u8;

    /// <summary>
    /// A variable controlling whether SDL will attempt to automatically set the destination display to a mode most
    /// closely matching that of the previous display if an exclusive fullscreen window is moved onto it.
    /// </summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_MATCH_EXCLUSIVE_MODE_ON_MOVE</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_MATCH_EXCLUSIVE_MODE_ON_MOVE</c>.</para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item>
    /// <description>"0": SDL will not attempt to automatically set a matching mode on the destination display. If an
    /// exclusive fullscreen window is moved to a new display, the window will become fullscreen desktop.</description>
    /// </item>
    /// <item>
    /// <description>"1": SDL will attempt to automatically set a mode on the destination display that most closely
    /// matches the mode of the display that the exclusive fullscreen window was previously on. (default)</description>
    /// </item>
    /// </list>
    /// <para>This hint can be set anytime.</para>
    /// <para>This hint is available since SDL 3.4.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoMatchExclusiveModeOnMove => "SDL_VIDEO_MATCH_EXCLUSIVE_MODE_ON_MOVE"u8;

    /// <summary>A variable controlling whether fullscreen windows are minimized when they lose focus.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_MINIMIZE_ON_FOCUS_LOSS</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_MINIMIZE_ON_FOCUS_LOSS</c>.</para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item><description>"0": Fullscreen windows will not be minimized when they lose focus.</description></item>
    /// <item><description>"1": Fullscreen windows are minimized when they lose focus.</description></item>
    /// <item>
    /// <description>"auto": Fullscreen windows are minimized when they lose focus if they use exclusive fullscreen
    /// modes, so the desktop video mode is restored. (default)</description>
    /// </item>
    /// </list>
    /// <para>This hint can be set anytime.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoMinimizeOnFocusLoss => "SDL_VIDEO_MINIMIZE_ON_FOCUS_LOSS"u8;

    /// <summary>A variable controlling whether the offscreen video driver saves output frames.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_OFFSCREEN_SAVE_FRAMES</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_OFFSCREEN_SAVE_FRAMES</c>.</para>
    /// <para>
    /// This only saves frames that are generated using software rendering, not accelerated OpenGL rendering.
    /// </para>
    /// <list type="bullet">
    /// <item><description>"0": Video frames are not saved to disk. (default)</description></item>
    /// <item>
    /// <description>"1": Video frames are saved to files in the format "SDL_windowX-Y.bmp", where X is the window ID,
    /// and Y is the frame number.</description>
    /// </item>
    /// </list>
    /// <para>This hint can be set anytime.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoOffscreenSaveFrames => "SDL_VIDEO_OFFSCREEN_SAVE_FRAMES"u8;

    /// <summary>A variable controlling whether all window operations will block until complete.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_SYNC_WINDOW_OPERATIONS</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_SYNC_WINDOW_OPERATIONS</c>.</para>
    /// <para>
    /// Window systems that run asynchronously may not have the results of window operations that resize or move the
    /// window applied immediately upon the return of the requesting function. Setting this hint will cause such
    /// operations to block after every call until the pending operation has completed. Setting this to '1' is the
    /// equivalent of calling SDL_SyncWindow() after every function call.
    /// </para>
    /// <para>
    /// Be aware that amount of time spent blocking while waiting for window operations to complete can be quite
    /// lengthy, as animations may have to complete, which can take upwards of multiple seconds in some cases.
    /// </para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item><description>"0": Window operations are non-blocking. (default)</description></item>
    /// <item><description>"1": Window operations will block until completed.</description></item>
    /// </list>
    /// <para>This hint can be set anytime.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoSyncWindowOperations => "SDL_VIDEO_SYNC_WINDOW_OPERATIONS"u8;

    /// <summary>A variable controlling whether the libdecor Wayland backend is allowed to be used.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_WAYLAND_ALLOW_LIBDECOR</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_WAYLAND_ALLOW_LIBDECOR</c>.</para>
    /// <para>libdecor is used over xdg-shell when xdg-decoration protocol is unavailable.</para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item><description>"0": libdecor use is disabled.</description></item>
    /// <item><description>"1": libdecor use is enabled. (default)</description></item>
    /// </list>
    /// <para>This hint should be set before SDL is initialized.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoWaylandAllowLibdecor => "SDL_VIDEO_WAYLAND_ALLOW_LIBDECOR"u8;

    /// <summary>A variable controlling whether video mode emulation is enabled under Wayland.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_WAYLAND_MODE_EMULATION</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_WAYLAND_MODE_EMULATION</c>.</para>
    /// <para>
    /// When this hint is set, a standard set of emulated CVT video modes will be exposed for use by the application. If
    /// it is disabled, the only modes exposed will be the logical desktop size and, in the case of a scaled desktop,
    /// the native display resolution.
    /// </para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item><description>"0": Video mode emulation is disabled.</description></item>
    /// <item><description>"1": Video mode emulation is enabled. (default)</description></item>
    /// </list>
    /// <para>This hint should be set before SDL is initialized.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoWaylandModeEmulation => "SDL_VIDEO_WAYLAND_MODE_EMULATION"u8;

    /// <summary>A variable controlling how modes with a non-native aspect ratio are displayed under Wayland.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_WAYLAND_MODE_SCALING</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_WAYLAND_MODE_SCALING</c>.</para>
    /// <para>
    /// When this hint is set, the requested scaling will be used when displaying fullscreen video modes that don't
    /// match the display's native aspect ratio. This is contingent on compositor viewport support.
    /// </para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item>
    /// <description>"aspect" - Video modes will be displayed scaled, in their proper aspect ratio, with black
    /// bars.</description>
    /// </item>
    /// <item>
    /// <description>"stretch" - Video modes will be scaled to fill the entire display. (default)</description>
    /// </item>
    /// <item><description>"none" - Video modes will be displayed as 1:1 with no scaling.</description></item>
    /// </list>
    /// <para>This hint should be set before creating a window.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoWaylandModeScaling => "SDL_VIDEO_WAYLAND_MODE_SCALING"u8;

    /// <summary>
    /// A variable controlling whether the libdecor Wayland backend is preferred over native decorations.
    /// </summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_WAYLAND_PREFER_LIBDECOR</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_WAYLAND_PREFER_LIBDECOR</c>.</para>
    /// <para>
    /// When this hint is set, libdecor will be used to provide window decorations, even if xdg-decoration is available.
    /// (Note that, by default, libdecor will use xdg-decoration itself if available).
    /// </para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item>
    /// <description>"0": libdecor is enabled only if server-side decorations are unavailable. (default)</description>
    /// </item>
    /// <item><description>"1": libdecor is always enabled if available.</description></item>
    /// </list>
    /// <para>This hint should be set before SDL is initialized.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoWaylandPreferLibdecor => "SDL_VIDEO_WAYLAND_PREFER_LIBDECOR"u8;

    /// <summary>A variable forcing non-DPI-aware Wayland windows to output at 1:1 scaling.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_WAYLAND_SCALE_TO_DISPLAY</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_WAYLAND_SCALE_TO_DISPLAY</c>.</para>
    /// <para>This must be set before initializing the video subsystem.</para>
    /// <para>
    /// When this hint is set, Wayland windows that are not flagged as being DPI-aware will be output with scaling
    /// designed to force 1:1 pixel mapping.
    /// </para>
    /// <para>
    /// This is intended to allow legacy applications to be displayed without desktop scaling being applied, and has
    /// issues with certain display configurations, as this forces the window to behave in a way that Wayland desktops
    /// were not designed to accommodate:
    /// </para>
    /// <list type="bullet">
    /// <item>
    /// <description>Rounding errors can result with odd window sizes and/or desktop scales, which can cause the window
    /// contents to appear slightly blurry.</description>
    /// </item>
    /// <item>
    /// <description>Positioning the window may be imprecise due to unit conversions and rounding.</description>
    /// </item>
    /// <item><description>The window may be unusably small on scaled desktops.</description></item>
    /// <item>
    /// <description>The window may jump in size when moving between displays of different scale factors.</description>
    /// </item>
    /// <item>
    /// <description>Displays may appear to overlap when using a multi-monitor setup with scaling enabled.</description>
    /// </item>
    /// <item>
    /// <description>Possible loss of cursor precision due to the logical size of the window being
    /// reduced.</description>
    /// </item>
    /// </list>
    /// <para>New applications should be designed with proper DPI awareness handling instead of enabling this.</para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item><description>"0": Windows will be scaled normally.</description></item>
    /// <item><description>"1": Windows will be forced to scale to achieve 1:1 output.</description></item>
    /// </list>
    /// <para>This hint should be set before creating a window.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintVideoWaylandScaleToDisplay => "SDL_VIDEO_WAYLAND_SCALE_TO_DISPLAY"u8;

    /// <summary>A variable specifying which shader compiler to preload when using the Chrome ANGLE binaries.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_VIDEO_WIN_D3DCOMPILER</c>.</para>
    /// <para>The value is <c>SDL_VIDEO_WIN_D3DCOMPILER</c>.</para>
    /// <para>
    /// SDL has EGL and OpenGL ES2 support on Windows via the ANGLE project. It can use two different sets of binaries,
    /// those compiled by the user from source or those provided by the Chrome browser. In the later case, these
    /// binaries require that SDL loads a DLL providing the shader compiler.
    /// </para>
    /// <para>The variable can be set to the following values:</para>
    /// <list type="bullet">
    /// <item><description>"d3dcompiler_46.dll" - best for Vista or later. (default)</description></item>
    /// <item><description>"d3dcompiler_43.dll" - for XP support.</description></item>
    /// <item>
