    /// <summary>
    /// A variable controlling whether menus can be opened with their keyboard shortcut (Alt+mnemonic).
    /// </summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_WINDOWS_ENABLE_MENU_MNEMONICS</c>.</para>
