    /// <item><description>"1": Alt+mnemonic opens menus, invalid mnemonics produce a beep.</description></item>
    /// </list>
    /// <para>This hint can be set anytime.</para>
    /// <para>This hint is available since SDL 3.2.0.</para>
    /// </remarks>
    public static ReadOnlySpan<byte> HintWindowsEnableMenuMnemonics => "SDL_WINDOWS_ENABLE_MENU_MNEMONICS"u8;

