    /// <summary>A variable controlling whether SDL uses Kernel Semaphores on Windows.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_HINT_WINDOWS_FORCE_SEMAPHORE_KERNEL</c>.</para>
